import { uv, vec3, vec4, mix, smoothstep, time, uniform, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CanvasTexture, Vector2 } = ctx.THREE;

  const group = new Group();
  const timelines = [];

  // ─────────────────────────────────────────────────────────────
  // 1. CANVAS TEXTURE: Card surface with gradient CTA and details
  // ─────────────────────────────────────────────────────────────
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 640; // 2.4 / 3.2 ratio scaled

  const ctx2d = canvas.getContext('2d');
  ctx2d.fillStyle = '#0b0b10';
  ctx2d.fillRect(0, 0, canvas.width, canvas.height);

  // Card background with border
  ctx2d.fillStyle = '#16161d';
  ctx2d.fillRect(8, 8, canvas.width - 16, canvas.height - 16);
  ctx2d.strokeStyle = '#2a2a33';
  ctx2d.lineWidth = 1.5;
  ctx2d.strokeRect(8, 8, canvas.width - 16, canvas.height - 16);

  // Machined header strip
  const headerGrad = ctx2d.createLinearGradient(0, 0, canvas.width, 0);
  headerGrad.addColorStop(0, '#3a3a42');
  headerGrad.addColorStop(0.5, '#2a2a33');
  headerGrad.addColorStop(1, '#3a3a42');
  ctx2d.fillStyle = headerGrad;
  ctx2d.fillRect(8, 8, canvas.width - 16, 25);

  // Tier name in header
  ctx2d.fillStyle = '#e8ecf2';
  ctx2d.font = '700 16px JetBrains Mono';
  ctx2d.letterSpacing = '2px';
  ctx2d.textAlign = 'left';
  ctx2d.fillText('ATELIER RESERVE', 30, 24);

  // Price
  ctx2d.fillStyle = '#e8ecf2';
  ctx2d.font = '600 54px Lora';
  ctx2d.textAlign = 'left';
  ctx2d.fillText('$480', 30, 95);

  // Price caption
  ctx2d.fillStyle = '#a8adb8';
  ctx2d.font = '400 8px JetBrains Mono';
  ctx2d.letterSpacing = '1px';
  ctx2d.textAlign = 'left';
  ctx2d.fillText('PER MONTH, BILLED ANNUALLY', 30, 102);

  // Feature rows with separators
  const features = [
    'Quarterly movement service',
    'Priority commission slots',
    'Private fitting lounge access',
    'Lifetime case refinishing'
  ];

  let featureY = 130;
  ctx2d.fillStyle = '#e8ecf2';
  ctx2d.font = '400 11px JetBrains Mono';
  ctx2d.textAlign = 'left';

  for (let i = 0; i < features.length; i++) {
    if (i > 0) {
      ctx2d.strokeStyle = '#23232b';
      ctx2d.lineWidth = 1;
      ctx2d.beginPath();
      ctx2d.moveTo(30, featureY - 8);
      ctx2d.lineTo(canvas.width - 30, featureY - 8);
      ctx2d.stroke();
    }
    ctx2d.fillText(features[i], 30, featureY);
    featureY += 50;
  }

  // CTA button with gradient
  const ctaGrad = ctx2d.createLinearGradient(0, 500, 0, 540);
  ctaGrad.addColorStop(0, '#ff4450');
  ctaGrad.addColorStop(1, '#c1121f');
  ctx2d.fillStyle = ctaGrad;
  ctx2d.fillRect(
    (canvas.width - 360) / 2,
    500,
    360,
    40
  );

  // CTA label
  ctx2d.fillStyle = '#16161d';
  ctx2d.font = '700 11px JetBrains Mono';
  ctx2d.letterSpacing = '1px';
  ctx2d.textAlign = 'center';
  ctx2d.fillText('JOIN THE RESERVE', canvas.width / 2, 523);

  const texture = new CanvasTexture(canvas);
  texture.magFilter = ctx.THREE.LinearFilter;
  texture.minFilter = ctx.THREE.LinearFilter;

  // ─────────────────────────────────────────────────────────────
  // 2. CARD PLANE MESH
  // ─────────────────────────────────────────────────────────────
  const cardGeo = new PlaneGeometry(2.4, 3.2);
  const cardMat = new MeshBasicNodeMaterial({
    map: texture,
    toneMapped: false,
  });

  const card = new Mesh(cardGeo, cardMat);
  card.position.set(0, 0, 0);
  card.scale.set(1, 1, 1);
  group.add(card);

  // ─────────────────────────────────────────────────────────────
  // 3. ACCENT RIM LIGHT (localised)
  // ─────────────────────────────────────────────────────────────
  const rimLight = new ctx.THREE.PointLight('#ff2a38', 1.2, 4);
  rimLight.position.set(1.5, 1, 0.8);
  group.add(rimLight);

  // ─────────────────────────────────────────────────────────────
  // 4. SETTLEMENT ANIMATION (scale 1.04 -> 1.0)
  // ─────────────────────────────────────────────────────────────
  card.scale.set(1.04, 1.04, 1);

  const settleTl = gsap.timeline();
  settleTl.to(
    card.scale,
    {
      x: 1,
      y: 1,
      duration: 0.9,
      ease: 'power4.out',
    },
    0
  );
  timelines.push(settleTl);

  // ─────────────────────────────────────────────────────────────
  // 5. FEATURE ROW STAGGER FADE-UP
  // ─────────────────────────────────────────────────────────────
  // Approximate feature row positions on canvas (visual approximation for stagger)
