  // or through the material's opacity. For this card, we'll layer a subtle
  // dissolve effect by animating the material's opacity with stagger.

  // Create a transparent plane for each feature row that fades in
  const featureRows = [];
  for (let i = 0; i < 4; i++) {
    const fGeo = new PlaneGeometry(2.0, 0.4);
    const fMat = new MeshBasicNodeMaterial({
      color: 0xffffff,
      transparent: true,
      opacity: 0,
    });
    const fMesh = new Mesh(fGeo, fMat);
    fMesh.position.y = 0.9 - i * 0.5;
    fMesh.position.z = 0.01; // Slight z-offset to sit atop card
    group.add(fMesh);
    featureRows.push({ mesh: fMesh, mat: fMat });
