  const staggerTl = gsap.timeline();
  featureRows.forEach((row, i) => {
    staggerTl.to(
      row.mesh.position,
      {
        y: row.mesh.position.y,
        duration: 0.5,
        ease: 'power2.out',
      },
      i * 0.08
    );
    staggerTl.to(
      row.mat,
      {
        opacity: 0,
        duration: 0.5,
        ease: 'power2.out',
      },
      i * 0.08
    );
  });
  timelines.push(staggerTl);

  // ─────────────────────────────────────────────────────────────
  // 6. CTA PRESS INTERACTION (scale 1.0 -> 0.97)
  // ─────────────────────────────────────────────────────────────
  const ctaPressTl = gsap.timeline({ paused: true });
  ctaPressTl.to(
    card.scale,
    {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out',
    },
    0
  );
  ctaPressTl.to(
    card.scale,
    {
      x: 1,
      y: 1,
      duration: 0.2,
      ease: 'power2.out',
    }
  );

  // ─────────────────────────────────────────────────────────────
  // 7. EVENT HANDLERS
  // ─────────────────────────────────────────────────────────────
  group.userData.handlers = {
    onCTAClick: () => {
      ctaPressTl.restart();
      ctx.emit('navigate', { to: 'hub-checkout' });
    },
  };

  // ─────────────────────────────────────────────────────────────
  // 8. CLEANUP
  // ─────────────────────────────────────────────────────────────
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    ctaPressTl.kill();
    cardMat.dispose();
    cardGeo.dispose();
    texture.dispose();
    canvas = null;

    featureRows.forEach(({ mesh, mat }) => {
      mat.dispose();
      mesh.geometry.dispose();
    });
  };

  return group;
}
